INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62871829', 62871829, 'analyze_legacy', 'Kota Yogyakarta', 'kabkota', 'Dinas Pertanahan dan Tata Ruang (Kundha Niti Mandala Sarta Tata Sasana)', 'Belanja Jasa Konsultansi Perorangan Penilaian Kesesuaian Kegiatan Pemanfaatan Ruang-2', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 38500000, 'January 2026', 'APBD', 1, 1, '1 orang x 11 bulan', 'Ruang lingkup pekerjaan Jasa Konsultansi Perorangan Penilaian Kesesuaian Kegiatan Pemanfaatan Ruang adalah membantu dalam pekerjaan Penilaian Kesesuaian Kegiatan Pemanfaatan Ruang (KKPR) di Dinas Pertanahan dan Tata Ruang (Kundha Niti Mandala Sarta Tata Sasana) Kota Yogyakarta, yang meliputi tahapan sebagai berikut: 1). Persiapan 2). Survey Lapangan 3). Analisis 4). Penilaian Pelaksanaan KKPR 5). Hasil Penilaian KKPR Lokasi pekerjaan berada di wilayah administrasi Kota Yogyakarta. Fasilitas yang dapat disediakan oleh PA adalah komputer, meteran, dan kamera.', 'Produk yang dihasilkan dari pekerjaan Jasa Konsultansi Perorangan Penilaian Kesesuaian Kegiatan Pemanfaatan Ruang dalam pekerjaan Penilaian Kesesuaian Kegiatan Pemanfaatan Ruang (KKPR) di Dinas Pertanahan dan Tata Ruang (Kundha Niti Mandala Sarta Tata Sasana) Kota Yogyakarta, meliputi tahapan sebagai berikut: 1). Persiapan a) Mengumpulkan Dokumen Kesesuaian Kegiatan Pemanfaatan Ruang; b) Menyiapkan Dokumen Penilaian Kesesuaian Kegiatan Pemanfaatan Ruang ; c) Menyiapkan alat bantu; d) Penyiapan perlengkapan survey Tim Penilai; e) Desk study; f) Koordinasi Tim Penilai; g) Pemberitahuan dan konfirmasi kepada pemegang KKPR 2}. Survey Lapangan a) Pemeriksaaan (Lokasi kegiatan, jenis kegiatan, indikasi program, persyaratan pelaksanaan kegiatan pemanfaatan ruang, jaringan utilitas kota) b) Pengukuran (KDB, KLB, Ketentuan Tata Bangunan, KDH, Garis Sempadan Bangunan, Jarak Bebas Bnagunan, Ketentuan Tapak Basement) c) Penandatanganan Berita Acara Pemeriksaan dan Pengukuran Kepatuhan Pelaksanaan Ketentuang KKPR 3). Analisis a) Analisis Kesesuaian Lokasi Kegiatan Pemanfaatan Ruang b) Analisis Kesesuaian Jenis Kegiatan Pemanfaatan Ruang c) Analisis Kesesuaian KDB d) Analisis Kesesuaian KLB e) Analisis Kesesuaian Ketentuan Tata Bangunan f) Analisis Kesesuaian Indikasi Program Pemanfaatan Ruang g) Analisis Kesesuaian Persyaratan Pelaksanaan Kegiatan Pemanfaatan Ruang h) Analisis Kesesuaian Garis Sempadan Bangunan i) Analisis Kesesuaian Jarak Bebas Bangunan j) Analisis Kesesuaian KDH k) Analisis Kesesuaian Koefisien Tapak Basement l) Analisis Kesesuaian Jaringan Utilitas Kota 4). Penilaian Pelaksanaan KKPR 5). Hasil Penilaian KKPR a) Periode Selama Pembangunan b) Periode Pasca Pembangunan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 210706);
