INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62116907', 62116907, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN TINGGI TATA USAHA NEGARA BANJARMASIN 01', 'Langganan Internet', 'Jasa Lainnya', 'E-Purchasing', 'Kalimantan Selatan, Banjar Baru (Kota)', 156000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 12, BLN, @ 13000000 )', '1. Langganan Internet ( 12, BLN, @ 13000000 );', 'SPESIFIKASI TEKNIS LAYANAN INTERNET DEDICATED FIBERNET 1. Ruang Lingkup Layanan Penyedia (Fibernet) menyediakan layanan akses internet utama (main link) dan cadangan (backup link) berbasis fiber optic yang beroperasi secara simultan, termasuk konfigurasi jaringan, untuk mendukung operasional sistem informasi Pengadilan Tinggi Tata Usaha Negara Banjarmasin. 2. Arsitektur Layanan Main Link : Internet Dedicated Fiber Backup Link : Internet Fiber Mode Operasi : Simultan / Active–Active Konfigurasi & Manajemen Trafik : Dilakukan oleh Fibernet 3. Spesifikasi Teknis Utama No Komponen Main (Utama) Backup (Cadangan) 1 Jenis Layanan Internet Dedicated Internet Fiber 2 Bandwidth 100 Mbps 200 Mbps 3 Rasio Bandwidth 1:1 (Dedicated) Up to / Best Effort 4 Media Akses Fiber Optic Fiber Optic 5 IP Address Public Static IPv4 Public Static IPv4 (opsional) 6 Availability ≥ 99% ≥ 98% 7 Latency Domestik ≤ 20 ms ≤ 30 ms 8 Packet Loss ≤ 1% ≤ 2% 9 Throughput ≥ 95% ≥ 90% 10 SLA Perbaikan Maks. 4 jam Maks. 6 jam 4. Konfigurasi & Manajemen oleh Fibernet Fibernet bertanggung jawab melakukan: Konfigurasi load balancing / policy routing Pengaturan active–active antara main dan backup link Pengujian koneksi simultan Penggabungan trafik tidak berarti agregasi bandwidth Pengaturan disesuaikan dengan kebutuhan operasional USER 5. Standar Kualitas Layanan (SLA) SLA Main Link minimal 99% SLA Backup Link minimal 98% Penyedia menyediakan kompensasi SLA sesuai kontrak Laporan performa bulanan terpisah untuk masing-masing link 6. Instalasi & Implementasi Instalasi fiber optic untuk dua jalur layanan Penyedia menyediakan dan mengkonfigurasi: ONT / media converter Router (jika disepakati dalam kontrak) Aktivasi layanan dibuktikan dengan Berita Acara Aktivasi (BAA) 7. Keamanan & Dukungan Aplikasi Mendukung VPN, IP Publik Firewall & filtering dasar (jika termasuk paket layanan) Tidak dilakukan throttling 8. Dukungan Teknis NOC & Helpdesk 24/7 Response time maksimal 1 jam Penanganan gangguan sesuai SLA masing-masing link 9. Masa Layanan Durasi kontrak: 12 bulan Layanan aktif penuh setelah BAA 10. Lokasi Layanan Pengadilan Tinggi Tata Usaha Negara Banjarmasin 11. Ketentuan Tambahan Mode simultan tidak mengubah sifat SLA masing-masing link Tidak ada biaya tambahan untuk konfigurasi awal Harga sudah termasuk pajak dan instalasi', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 210996);
