INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62116888', 62116888, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN TINGGI TATA USAHA NEGARA BANJARMASIN 01', 'Petugas Kebersihan', 'Jasa Lainnya', 'E-Purchasing', 'Kalimantan Selatan, Banjar Baru (Kota)', 265005000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 65, Ob, @ 4077000 )', 'Petugas Kebersihan 5 Orang x 13 Bulan ( 65, Ob, @ 4077000 );', 'SPESIFIKASI PEKERJAAN OUTSOURCING PETUGAS KEBERSIHAN 1. Nama Pekerjaan Pengadaan Jasa Outsourcing Petugas Kebersihan 2. Satuan Kerja Pengadilan Tinggi Tata Usaha Negara Banjarmasin 3. Ruang Lingkup Pekerjaan Penyedia jasa bertanggung jawab menyediakan tenaga Petugas Kebersihan untuk melaksanakan kegiatan kebersihan dan pemeliharaan lingkungan kantor, meliputi: Ruang kerja pimpinan dan pegawai Ruang sidang Ruang arsip dan ruang pelayanan publik Toilet dan kamar mandi Area lobi, koridor, tangga, dan lift Halaman, taman, dan area parkir Area pendukung lainnya di lingkungan kantor 4. Volume dan Jangka Waktu Uraian Keterangan Jumlah Petugas 5 (lima) orang Masa Kontrak 13 (tiga belas) bulan Volume 65,00 OB (Orang Bulan) 5. Jam Kerja Hari kerja: Senin s.d. Jumat Jam kerja: 07.30 – 16.00 WITA Menyesuaikan kebutuhan operasional kantor dan kegiatan kedinasan 6. Kualifikasi Petugas Petugas Kebersihan yang disediakan oleh Penyedia harus memenuhi persyaratan: Warga Negara Indonesia Usia minimal 20 tahun dan maksimal 50 tahun Pendidikan minimal SMP/sederajat Sehat jasmani dan rohani (dibuktikan surat keterangan dokter) Berperilaku baik (dibuktikan SKCK) Berpengalaman di bidang kebersihan (diutamakan) Berpenampilan rapi, sopan, dan disiplin 7. Tugas dan Tanggung Jawab Petugas Kebersihan wajib: Menjaga kebersihan lantai, dinding, meja, kursi, kaca, dan peralatan kantor Membersihkan toilet dan memastikan ketersediaan perlengkapan kebersihan Mengelola sampah dan pembuangan sampah secara rutin Membersihkan halaman dan area luar gedung Melaksanakan pembersihan berkala (harian, mingguan, dan bulanan) Menjaga etika, sopan santun, dan kerahasiaan lingkungan kerja peradilan 8. Peralatan dan Bahan Kebersihan Penyedia wajib menyediakan: Peralatan kebersihan (sapu, pel, vacuum cleaner, alat kebersihan taman, dll.) Bahan habis pakai (pembersih lantai, kaca, toilet, pengharum ruangan, dll.) Alat Pelindung Diri (APD) sesuai standar keselamatan kerja 9. Seragam dan Identitas Penyedia wajib menyediakan seragam kerja lengkap dan tanda pengenal Seragam harus rapi, sopan, dan mencerminkan profesionalisme 10. Penggajian dan Kesejahteraan Upah petugas sesuai ketentuan peraturan perundang-undangan (UMR/UMK setempat) Penyedia wajib mendaftarkan petugas pada BPJS Kesehatan dan BPJS Ketenagakerjaan Seluruh kewajiban ketenagakerjaan menjadi tanggung jawab Penyedia 11. Pengawasan dan Evaluasi Pelaksanaan pekerjaan diawasi oleh Pejabat/Pengawas dari PTTUN Banjarmasin Evaluasi kinerja dilakukan secara berkala Penyedia wajib mengganti petugas yang tidak memenuhi standar kinerja 12. Harga dan Nilai Pekerjaan Uraian Nilai Harga Satuan Rp4.077.000,- / OB Volume 65,00 OB Jumlah Rp265.005.000,- Terbilang Dua ratus enam puluh lima juta lima ribu rupiah 13. Ketentuan Lain-lain Penyedia wajib mematuhi seluruh peraturan yang berlaku di lingkungan peradilan Dilarang mengalihkan pekerjaan kepada pihak lain tanpa persetujuan tertulis Kerusakan atau kehilangan akibat kelalaian petugas menjadi tanggung jawab Penyedia', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 212085);
