INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62117435', 62117435, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA PUSAT', 'Penyusunan Dokumen Teknis Gedung Pemda - SAPS 8 (Arsitektur) 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 82582500, 'December 2025', 'APBD', 1, 1, '1 Paket', '"Lingkup kegiatan yang dilakukan oleh penyedia jasa Senior Assistant Professional Staff (SAPS) 8 - Arsitektur, meliputi: a. Membantu melakukan pembuatan laporan hasil survei bangunan gedung existing berupa dokumen kajian/rekomendasi teknis tingkat kerusakan bidang arsitektur berdasarkan dengan pendekatan peraturan yang berlaku; b. Membantu penyusunan perencanaan teknis pembangunan, perawatan dan pemeliharaan bangunan gedung pemerintah daerah; dan c. Membantu melakukan pembuatan besaran nilai anggaran kebutuhan rehab/perawatan bidang arsitektur sesuai dengan Standar Harga Satuan Tertinggi. "', '"Senior Assistant Profesional Staff bidang Arsitektur dengan ketentuan sebagai berikut : Pendidikan Minimal S1/D4/Setara Jurusan Arsitektur dari Universitas Negeri/ Swasta dengan status lain yang telah mengikuti ujian negara atau lulusan luar negeri bagi penyedia jasa Senior Assistant Professional Staff; Memiliki kompetensi sesuai bidang yang dipersyaratkan yang dibuktikan dengan ijazah dan transkrip nilai pendidikan terakhir Jurusan Arsitektur, sertifikat keahlian/teknis seperti aplikasi Sketch-Up / AutoCAD / Adobe (Photoshop/InDesign/Illustrator) / Lumi-on/3D Max, Microsoft Office dan/atau sertifikat pelatihan/kursus; dan Pengalaman Kerja minimal 1 tahun di bidang perencanaan, pembangunan, perawatan bangunan gedung dan/atau pekerjaan sejenis. "', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 212495);
