INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62118896', 62118896, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA PUSAT', 'Penyusunan Dokumen Teknis Gedung Pemda - SAPS 11 (Struktur) 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 82582500, 'December 2025', 'APBD', 1, 1, '1 Paket', '"Lingkup kegiatan yang dilakukan oleh penyedia jasa Senior Assistant Professional Staff (SAPS) 11 - Struktur, meliputi: a. Membantu memeriksa dan mengkaji kembali (review) dokumen struktur perencanaan yang dibuat oleh jasa konsultan perencana maupun yang dibuat oleh Seksi Pembinaan Gedung Pemda (in house) terutama di awal pelaksanaan pembangunan pekerjaan fisik dan menyampaikan usulan penyempurnaan bila didapati kekurangan/ketidaksesuaian dalam perencanaan konsultan, sehingga pekerjaan dapat dilaksanakan secara efektif, efisien dan bangunan nantinya dapat berfungsi secara optimal ; b. Membantu memeriksa dan mengkaji kembali (review) kesesuaian volume pekerjaan struktur antara gambar kerja dengan Rencana Anggaran Biaya (RAB) terutama di awal pelaksanaan pekerjaan fisik dan menyampaikan usulan penyempurnaan bila didapati ketidaksesuaian; c. Membantu mengawasi pelaksanaan pekerjaan struktur yang dilaksanakan oleh Kontraktor dari segi kualitas, kuantitas dan laju pencapaian prestasi pekerjaan; d. Melaporkan dan memberikan saran atas hasil pekerjaan struktur yang tidak memenuhi persyaratan; dan e. Membantu membuat kelengkapan administrasi sebagai bagian dari penertiban pelaksanaan pembangunan fisik sesuai dengan ketentuan yang berlaku. "', '"Senior Assistant Profesional Staff bidang Struktur dengan ketentuan sebagai berikut : a. Pendidikan Minimal S1/D4/Setara Jurusan Teknik Sipil dari Universitas Negeri/ Swasta dengan status lain yang telah mengikuti ujian negara atau lulusan luar negeri bagi penyedia jasa Senior Assistant Professional Staff; b. Memiliki kompetensi sesuai bidang yang dipersyaratkan yang dibuktikan dengan ijazah dan transkrip nilai pendidikan terakhir Jurusan Teknik Sipil sertifikat keahlian/teknis seperti aplikasi AutoCAD, SAP 2000/Etabs, Microsoft Office dan/atau sertifikat pelatihan/kursus; dan c. Pengalaman Kerja minimal 1 tahun di bidang perencanaan, pembangunan, perawatan bangunan gedung dan/atau pekerjaan sejenis. "', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 213083);
