INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62119931', 62119931, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA PUSAT', 'Penyusunan Dokumen Teknis Gedung Pemda - SAPS 12 (Struktur) 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 82582500, 'December 2025', 'APBD', 1, 1, '1 Paket', '"Lingkup kegiatan yang dilakukan oleh penyedia jasa Senior Assistant Professional Staff (SAPS) 12 - Struktur, meliputi: a. Membantu penyusunan perencanaan teknis (bidang struktur) pembangunan, perawatan dan pemeliharaan bangunan gedung pemerintah daerah; b. Membantu pemeriksaan kelengkapan standar teknis bangunan gedung dan penerbitan surat pernyataan pemenuhan standar teknis dalam rangka Persetujuan Bangunan Gedung (PBG) dan Sertifikat Laik Fungsi (SLF) bangunan Gedung; c. Memeriksa shop drawing dan as built drawing serta membantu dalam pembuatan as built drawing (Bidang Struktur) gedung pemerintah daerah; d. Membantu mendokumentasikan data dan dokumen terkait bangunan dan lahan, termasuk perizinan gedung pemda; dan e. Membantu mendokumentasikan hasil peninjauan lapangan dalam rangka perencanaan, perawatan dan pemeliharaan serta pembangunan gedung pemda. "', '"Senior Assistant Profesional Staff bidang Struktur dengan ketentuan sebagai berikut : a. Pendidikan Minimal S1/D4/Setara Jurusan Teknik Sipil dari Universitas Negeri/ Swasta dengan status lain yang telah mengikuti ujian negara atau lulusan luar negeri bagi penyedia jasa Senior Assistant Professional Staff; b. Memiliki kompetensi sesuai bidang yang dipersyaratkan yang dibuktikan dengan ijazah dan transkrip nilai pendidikan terakhir Jurusan Teknik Sipil sertifikat keahlian/teknis seperti aplikasi AutoCAD, SAP 2000/Etabs, Microsoft Office dan/atau sertifikat pelatihan/kursus; dan c. Pengalaman Kerja minimal 1 tahun di bidang perencanaan, pembangunan, perawatan bangunan gedung dan/atau pekerjaan sejenis. "', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 213346);
