INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62116865', 62116865, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN TINGGI TATA USAHA NEGARA BANJARMASIN 01', 'Satpam', 'Jasa Lainnya', 'E-Purchasing', 'Kalimantan Selatan, Banjar Baru (Kota)', 349830000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 78, Ob, @ 4485000 )', 'Satpam 6 Orang x 13 Bulan ( 78, Ob, @ 4485000 );', 'SPESIFIKASI PEKERJAAN JASA OUTSOURCING SATUAN PENGAMANAN (SATPAM) 1. Nama Paket Pekerjaan Jasa Outsourcing Satuan Pengamanan (Satpam) 2. Ruang Lingkup Pekerjaan Penyedia menyediakan tenaga Satuan Pengamanan (Satpam) untuk melaksanakan tugas pengamanan di lingkungan kerja instansi, yang meliputi: Pengamanan aset, gedung, sarana dan prasarana Pengaturan lalu lintas keluar masuk orang dan kendaraan Pemeriksaan tamu, barang, dan kendaraan Pencegahan dan penanggulangan gangguan keamanan Pelaporan kejadian keamanan secara berkala Penegakan tata tertib dan prosedur keamanan internal Koordinasi dengan aparat keamanan setempat bila diperlukan 3. Jumlah dan Periode Penugasan Uraian Keterangan Jumlah Tenaga 6 (enam) orang Satpam Periode Kontrak 13 (tiga belas) bulan Volume 78 Orang/Bulan (OB) Sistem Kerja Shift sesuai kebutuhan operasional Lokasi Sesuai lokasi kerja instansi 4. Kualifikasi Tenaga Satpam Setiap tenaga Satpam wajib memenuhi persyaratan berikut: Warga Negara Indonesia Usia minimal 21 tahun dan maksimal 45 tahun Pendidikan minimal SMA/sederajat Memiliki Sertifikat Gada Pratama yang masih berlaku Memiliki KTA Satpam aktif Sehat jasmani dan rohani (dibuktikan surat keterangan dokter) Tidak memiliki catatan kriminal (SKCK aktif) Berpengalaman minimal 1 (satu) tahun di bidang pengamanan Berpenampilan rapi, disiplin, dan beretika baik 5. Tugas dan Tanggung Jawab Penyedia Penyedia bertanggung jawab penuh atas: Rekrutmen dan penempatan tenaga Satpam Pembayaran gaji sesuai ketentuan peraturan perundang-undangan Kepesertaan BPJS Kesehatan dan BPJS Ketenagakerjaan Penyediaan seragam, atribut, dan perlengkapan Satpam Penggantian personel apabila tidak memenuhi kinerja Pembinaan dan pengawasan kinerja Satpam Menyediakan supervisor/koordinator lapangan 6. Jam Kerja dan Pola Shift Jam kerja mengikuti kebutuhan operasional instansi Sistem shift (pagi/siang/malam) atau jam kerja khusus Penyesuaian jadwal dilakukan atas persetujuan Pejabat Pengguna 7. Standar Kinerja Tenaga Satpam wajib: Hadir tepat waktu dan sesuai jadwal Mematuhi SOP keamanan instansi Bersikap sopan, ramah, dan profesional Menjaga kerahasiaan informasi instansi Membuat laporan kegiatan harian dan kejadian khusus 8. Spesifikasi Harga dan Nilai Kontrak Uraian Nilai Harga Satuan Rp 4.485.000 / OB Volume 78 OB Jumlah Rp 349.830.000 Terbilang Tiga ratus empat puluh sembilan juta delapan ratus tiga puluh ribu rupiah 9. Ketentuan Lain-Lain Penyedia wajib mematuhi seluruh ketentuan ketenagakerjaan Tenaga Satpam berada di bawah pengawasan Penyedia Evaluasi kinerja dilakukan secara berkala oleh pengguna Sanksi dapat diberikan apabila penyedia tidak memenuhi kewajiban', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 214939);
