INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62117647', 62117647, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA PUSAT', 'Penyusunan Dokumen Teknis Gedung Pemda - SAPS 9 (Arsitektur) 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 82582500, 'December 2025', 'APBD', 1, 1, '1 Paket', '"Lingkup kegiatan yang dilakukan oleh penyedia jasa Senior Assistant Professional Staff (SAPS) 9 - Arsitektur, meliputi: a. Membantu memeriksa dan mengkaji kembali (review) kesesuaian volume pekerjaan antara gambar kerja dengan Rencana Anggaran Biaya (RAB) terutama di awal pelaksanaan pekerjaan fisik dan menyampaikan usulan penyempurnaan bila didapati ketidaksesuaian; b. Membantu tugas-tugas Pejabat Pembuat Komitmen dalam menjamin pekerjaan konstruksi/fisik gedung sesuai dengan dokumen kontrak, kecuali jika disepakati dan mendapat persetujuan untuk dilakukannya perubahan; c. Membantu mengawasi pelaksanaan yang dilaksanakan oleh Kontraktor dari segi kualitas, kuantitas dan laju pencapaian prestasi pekerjaan; dan Melakukan review dan memberikan saran atau masukan atas hasil pekerjaan yang tidak memenuhi persyaratan "', '"Senior Assistant Profesional Staff bidang Arsitektur dengan ketentuan sebagai berikut : a.Pendidikan Minimal S1/D4/Setara dari Jurusan Arsitektur Universitas Negeri/ Swasta dengan status lain yang telah mengikuti ujian negara atau lulusan luar negeri bagi penyedia jasa Senior Assistant Professional Staff; b. Memiliki kompetensi sesuai bidang yang dipersyaratkan yang dibuktikan dengan ijazah dan transkrip nilai pendidikan terakhir Jurusan Arsitektur, sertifikat keahlian/teknis seperti aplikasi Sketch-Up / AutoCAD / Adobe (Photoshop/InDesign/Illustrator) / Lumi-on/3D Max, Microsoft Office dan/atau sertifikat pelatihan/kursus; dan c. Pengalaman Kerja minimal 1 tahun di bidang perencanaan, pembangunan, perawatan bangunan gedung dan/atau pekerjaan sejenis. "', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 216606);
