INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62896119', 62896119, 'analyze_legacy', 'Kementerian Pendidikan Dasar dan Menengah', 'central', 'BPMP PROVINSI PAPUA', 'Pemeliharaan Ruang Kelas Media', 'Barang', 'Pengadaan Langsung', 'Papua, Jayapura (Kota)', 150000000, 'January 2026', 'APBN', 1, 1, '1 Paket', 'Melaksanakan pemeliharaan ruang kelas media guna menjaga fungsi, kenyamanan, dan kelayakan ruang pembelajaran melalui kegiatan pemeriksaan kondisi ruangan, pembersihan, perbaikan ringan, serta penggantian komponen yang mengalami kerusakan agar ruang kelas media dapat digunakan secara optimal dalam mendukung kegiatan pembelajaran.', 'Pekerjaan pemeliharaan ruang kelas media meliputi pemeriksaan kondisi ruang kelas dan perlengkapannya, pembersihan area ruangan, perbaikan ringan pada bagian bangunan yang mengalami kerusakan ringan, perbaikan atau penggantian perlengkapan media pembelajaran yang rusak, serta pengecekan dan perbaikan sarana pendukung lainnya. Seluruh pekerjaan dilaksanakan sesuai ketentuan teknis dan standar keselamatan yang berlaku agar ruang kelas media tetap layak, aman, dan nyaman digunakan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 217092);
