INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62896120', 62896120, 'analyze_legacy', 'Kementerian Pendidikan Dasar dan Menengah', 'central', 'BPMP PROVINSI PAPUA', 'Pemeliharaan Ruang Lab. Komputer', 'Barang', 'Pengadaan Langsung', 'Papua, Jayapura (Kota)', 150000000, 'January 2026', 'APBN', 1, 1, '1 Paket', 'Melaksanakan pemeliharaan ruang laboratorium komputer guna menjaga fungsi, keamanan, dan kenyamanan ruang serta mendukung kelancaran kegiatan pembelajaran melalui pemeriksaan kondisi ruangan dan sarana pendukung, pembersihan, perbaikan ringan, serta penggantian komponen yang mengalami kerusakan agar ruang laboratorium komputer dapat digunakan secara optimal.', 'Pekerjaan pemeliharaan ruang laboratorium komputer meliputi pemeriksaan kondisi ruang dan perlengkapannya, pembersihan area ruangan, perbaikan ringan pada bagian bangunan yang mengalami kerusakan ringan, pengecekan dan perbaikan instalasi listrik dan jaringan, serta perbaikan atau penggantian sarana pendukung lainnya yang rusak. Seluruh pekerjaan dilaksanakan sesuai ketentuan teknis dan standar keselamatan kerja yang berlaku agar ruang laboratorium komputer tetap layak, aman, dan nyaman digunaka', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 217094);
