INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63955568', 63955568, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Pembinaan dan Monitoring', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 500000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Kegiatan pembinaan dan monitoring dilaksanakan untuk meningkatkan pemahaman, kepatuhan, dan kualitas pelaksanaan tugas dan kegiatan, serta memastikan pelaksanaan program berjalan sesuai ketentuan dan target yang telah ditetapkan. Ruang lingkup kegiatan meliputi: 1. Pembinaan teknis dan administratif kepada unit kerja/pelaksana. 2. Monitoring pelaksanaan program dan kegiatan secara berkala. 3. Identifikasi permasalahan dan hambatan pelaksanaan. 4. Penyampaian arahan, masukan, dan rekomendasi perbaikan. Kegiatan ini bertujuan untuk memperkuat koordinasi, meningkatkan kinerja, serta menjamin kesesuaian pelaksanaan kegiatan dengan kebijakan dan peraturan yang berlaku.', '1. Pembinaan o Pemberian arahan, bimbingan, dan pendampingan teknis. o Penyampaian kebijakan, pedoman, dan ketentuan pelaksanaan kegiatan. o Konsultasi dan klarifikasi permasalahan pelaksanaan di unit kerja. 2. Monitoring o Pemantauan pelaksanaan kegiatan sesuai rencana dan jadwal. o Pengumpulan dan verifikasi data pelaksanaan dan capaian kinerja. o Penilaian kesesuaian pelaksanaan dengan ketentuan yang berlaku. 3. Pelaporan dan Tindak Lanjut o Penyusunan laporan hasil pembinaan dan monitoring. o Penyampaian rekomendasi dan rencana tindak lanjut perbaikan. 4. Standar Pelaksanaan o Dilaksanakan sesuai peraturan perundang-undangan. o Mengedepankan prinsip objektivitas, akuntabilitas, dan transparansi. 5. Hasil yang Diharapkan o Meningkatnya kualitas dan kepatuhan pelaksanaan kegiatan. o Tersedianya laporan pembinaan dan monitoring sebagai bahan evaluasi dan pengambilan keputusan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 218752);
