INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123450', 62123450, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA JOMBANG01', 'Pengadaan Jasa Outsourcing Satpam dan Petugas Kebersihan Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Jombang (Kab.)', 451568000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '104 Orang Bulan (OB)', '1. Satpam ( 52, OB, @ 4.549.000 ) 2. Petugas Kebersihan ( 52, OB, @ 4.135.000 )', 'Job Description untuk Satpam : 1) Menjaga dan memastikan keamanan lalu lintas keluar masuk kantor baik Pegawai maupun Pihak Berperkara, dengan pembagian pekerjaan Satpam sesuai jadwal yang telah ditetapkan serta menyeberangkan pihak dan pegawai baik masuk maupun keluar kantor; 2) Mengatur pembagian ID Card kepada para Pihak; 3) Menjaga area parkir Kendaraan Roda 2 Dan Roda 4 seluruh area kantor; 4) Menjaga keamanan seluruh keamanan kantor dan isinya di dalam lingkungan PA. Jombang; 5) Melaksanakan jaga malam bagi satpam yang jaga di pos, dikecualikan bagi satpam yang menjaga di bagian pelayanan; 6) Menyalakan lampu halaman depan saat malam pukul 18.00 dan mematikan pada pukul 05.00 WIB serta melaporkan dan mengganti lampu saat ada kerusakan. Job Description untuk Petugas Kebersihan : 1) Membersihan seluruh area gedung kantor dalam hal dalam hal menyapu lantai, mengepel, membuang sampah, mencuci tempat sampah, menguras kamar mandi dan mengelap kaca; 2) Melaksanakan pemeliharaan kebersihan halaman gedung kantor dan taman; 3) Menguras dan mengecek kebersihan kamar mandi umum, kamar mandi pegawai dan kamar mandi disabilitas serta menjaga kebersihan setiap hari. 4) Membersihkan dan mengelap seluruh meja dan kursi pegawai, meja dan kursi ruang pertemuan serta ruang pelayanan dan sidang.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 218784);
