INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62896123', 62896123, 'analyze_legacy', 'Kementerian Pendidikan Dasar dan Menengah', 'central', 'BPMP PROVINSI PAPUA', 'Pemelihaaan Printer', 'Barang', 'Pengadaan Langsung', 'Papua, Jayapura (Kota)', 6900000, 'January 2026', 'APBN', 1, 1, '1 Paket', 'Melaksanakan pemeliharaan printer guna menjaga kinerja, keandalan, dan kualitas hasil cetak melalui kegiatan pemeriksaan kondisi perangkat, pembersihan, perawatan rutin, perbaikan ringan, serta penggantian komponen yang mengalami kerusakan agar printer dapat berfungsi secara optimal dalam mendukung kegiatan operasional.', 'Pekerjaan pemeliharaan printer meliputi pemeriksaan kondisi unit printer, pembersihan bagian dalam dan luar printer, pengecekan fungsi mekanik dan elektronik, perbaikan atau penggantian komponen printer yang mengalami kerusakan ringan, serta pengujian hasil cetak setelah pemeliharaan. Seluruh pekerjaan dilaksanakan sesuai ketentuan teknis dan standar keselamatan kerja yang berlaku agar printer berfungsi dengan baik, aman, dan menghasilkan cetakan yang optimal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 218954);
