INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123075', 62123075, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Pemeliharaan Sistem TCWC dan SATAID-T', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 300000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pemeliharaan Sistem TCWC dan SATAID-T adalah sistem MEWS (Meteorology Early Warning System) yang merupakan sistem peringatan dini yang beroperasi selama 24 jam 7 hari. Sistem TCWC Jakarta menggunakan sistem peringatan dini siklon tropis yang dikembangkan oleh BoM (Bureau of Meteorology), Australia yaitu TC Module dengan sistem utama sebagai analisis, pengolahan dan produksi. Selain itu TCWC Jakarta juga menggunakan sistem analisis citra satelit untuk siklon tropis dari Jepang, JMA (Japan Meteorological Agency), yaitu Sataid-T. Sistem operasional TCWC terdiri dari modul (TC Modul dan Sataid-T) yang digunakan untuk proses pengolahan dan produksi. Pada proses pengolahan terdiri dari proses analisis, proses input, proses pembuatan trajectory siklon tropis, dan pembuatan prakiraan. Pada proses produksi adalah pembuatan produk-produk peringatan dini siklon tropis baik berupa teks dan grafis serta diseminasinya. Produk-produk peringatan dini siklon tropis yang dihasilkan oleh sistem TCWC Jakarta merupakan produk-produk yang sangat penting dengan tingkat urgensi tinggi yang bermanfaat dalam mendukung salah satu tugas BMKG yaitu memberikan peringatan dini cuaca ekstrem, meningkatkan kewaspadaan masyarakat terkait cuaca ekstrem, menjaga keselamatan masyarakat akibat dampak bencana yang ditimbulkan, dan mendukung peran serta instansi pemerintah lainnya dalam menghadapi bencana yang dapat ditimbulkan oleh fenomena siklon tropis di wilayah Indonesia.', 'Kegiatan ini terdiri dari : Kegiatan Preventive Maintenance (PM) dan Corrective Maintenance (CM) peralatan dan mesin sistem TCWC Jakarta dan Sataid-T, Pemeliharaan dan pengembangan tools pengolahan dan produksi produk peringatan dini siklon tropis TCWC Jakarta, Pemeliharaan dan pengembangan fitur website TCWC Jakarta, Pengembangan produk TCWC Jakarta. dan Pembelian lisensi tahunan untuk perangkat lunak yang mendukung kegiatan operasional.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 219100);
