INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123073', 62123073, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Pemeliharaan Sistem Operasional Cuaca Ekstrem', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 200000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Sistem', 'Salah satu tugas dan fungsi utama BMKG adalah menyediakan informasi Prediksi dan Peringatan Dini Cuaca Fenomena Cuaca Khusus dalam berbagai skala waktu. Sistem cuaca ekstrem telah diinisiasi melalui berbagai program sejak tahun 2008 baik melalui sistem yang dibuat mandiri (in-house) maupun yang melalui pengadaan dengan pihak ketiga. Kompleksitas alur pengelolaan cuaca ekstrem menjadi semakin meningkat karena sistem yang dibuat di awal tidak disiapkan untuk memiliki fungsi untuk interoperability. Sedangkan kebutuhan operasional sistem Prediksi dan Peringatan Dini Cuaca Fenomena Cuaca Khusus dibutuhkan setiap saat oleh operator atau forecaster dan wajib didesiminasikan ke masyarakat luas. Oleh karena itu pekerjaan Pemeliharaan Sistem Operasional Cuaca Ekstrem memiliki tingkat urgensi dan risiko yang tinggi. Ketersediaan informasi Prediksi dan Peringatan Dini Cuaca Fenomena Cuaca Khusus tentang Cuaca Ekstrem sangat penting dimana dampaknya dapat membahayakan jiwa dan menimbulkan kerugian harta benda. Sistem Operasional Cuaca Ekstrem di tim kerja Prediksi dan Peringatan Dini Cuaca Fenomena Cuaca Khusus tahun 2025 dalam kegiatan Pemeliharaan Sistem Operasional Cuaca Ekstrem, yaitu Sistem Informasi Manajemen Bencana Hidrometeorologi akibat Cuaca Ekstrem.', 'Ruang lingkup dari kegiatan Pemeliharaan Sistem Operasional Cuaca Ekstrem tahun 2025 ini adalah : Pemeliharaan sistem baik dari hardware hingga software dan jaringannya, Sistem Informasi Manajemen Bencana Hidrometeorologi akibat Cuaca Ekstrem, Pekerjaan Preventive dan Corrective maintenance, Pengaktifan lisensi dan Pembelian barang dan pemasangan suku cadang peralatan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 219114);
