INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123096', 62123096, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Sewa jaringan komunikasi sinkronisasi tanda waktu', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 160000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', 'Untuk memastikan seluruh pihak yang terlibat menggunakan referensi waktu yang sama, diperlukan layanan penyeragaman/sinkronisasi tanda waktu yang terhubung melalui sistem komunikasi yang stabil. Sistem ini berfungsi sebagai media distribusi referensi waktu dari BMKG Pusat ke pihak-pihak yang memerlukan penyelarasan waktu sebagai acuan siaran/layanan, yaitu TVRI, RRI, dan Stasiun Radio Pantai Bekasi. Dengan adanya jaringan sinkronisasi tanda waktu tersebut, proses penyampaian informasi dapat berjalan lebih tertib, terukur, dan konsisten, serta mendukung akurasi operasional BMKG secara menyeluruh. Oleh karena itu, diperlukan sewa layanan komunikasi sinkronisasi tanda waktu yang mampu menjamin konektivitas dan kontinuitas layanan secara berkelanjutan, dengan tingkat keandalan yang sesuai untuk operasi real time 24x7.', 'Spesifikasi teknis layanan adalah penyediaan Sewa VPN IP untuk mendukung komunikasi LAN-to-LAN (intranet) antar lokasi BMKG Pusat dengan RRI, TVRI, dan Stasiun Radio Pantai Bekasi. Pada BMKG Pusat disediakan layanan VPN IP dengan bandwidth 1.024 Kbps (1 Mbps) termasuk perangkat router dan modul E&M, sedangkan pada RRI, TVRI, dan Stasiun Radio Pantai Bekasi masing-masing disediakan layanan VPN IP dengan bandwidth 128 Kbps termasuk perangkat router dan modul E&M. Layanan harus mampu mengakomodasikan protokol TCP/IP serta mendukung kebutuhan komunikasi data dengan karakteristik trafik rendah hingga menengah/tinggi sesuai kebutuhan operasional sinkronisasi tanda waktu.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 219387);
