INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123060', 62123060, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Renewal update lisensi aplikasi monitoring', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 270000000, 'July 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '1, LISEN', 'Dalam melaksanakan tugas operasional maupun kegiatan dukungan manajemen, BMKG memanfaatkan berbagai aplikasi monitoring yang masing-masing memiliki sistem manajemen akses sendiri. Memonitor IP dengan IPAM (Manajemen Alamat IP) adalah proses fundamental untuk mengelola dan mengawasi penggunaan alamat IP dalam jaringan. IPAM menyediakan visibilitas dan kontrol terpusat yang jauh lebih efisien daripada metode manual seperti spreadsheet. Fungsi Utama IPAM dalam Monitoring IP : Pelacakan dan Audit: IPAM secara otomatis melacak setiap alamat IP dalam jaringan, termasuk informasi seperti alamat MAC, nama perangkat, nama pengguna, dan stempel waktu saat IP dialokasikan. Hal ini memungkinkan administrator untuk mengaudit siapa yang menggunakan IP tertentu, kapan, dan di mana. Deteksi Konflik: IPAM secara proaktif mendeteksi dan mencegah konflik alamat IP yang dapat terjadi saat dua perangkat memiliki alamat IP yang sama. Sistem ini akan memberi peringatan kepada administrator tentang adanya alamat IP duplikat atau subnet yang tumpang tindih, Visualisasi Jaringan: IPAM menyediakan peta atau dashboard visual yang menampilkan status real-time dari seluruh ruang alamat IP. Administrator dapat dengan mudah melihat mana IP yang tersedia, mana yang sedang digunakan, dan mana yang dicadangkan, Pelaporan Komprehensif: IPAM dapat menghasilkan laporan terperinci tentang penggunaan IP, tren, dan aktivitas jaringan. Laporan ini dapat digunakan untuk perencanaan kapasitas, pemecahan masalah, atau untuk memastikan kepatuhan terhadap kebijakan jaringan.', 'EfficientIP, perangkat lunak yang dirancang khusus untuk mengelola layanan DDI (DNS-DHCP-IPAM) dalam satu platform terpadu. Alih-alih mengelola setiap layanan secara terpisah menggunakan alat yang berbeda (seperti spreadsheet atau server DNS/DHCP mandiri), solusi DDI dari EfficientIP menyatukan semuanya untuk menyederhanakan manajemen, meningkatkan keamanan, dan mengotomatisasi alur kerja. Monitoring adalah aspek penting dari solusi DDI, yang membantu administrator terus mengawasi status jaringan, mendeteksi anomali, dan memastikan performa optimal. Sebagai alat strategis, solusi EfficientIP SOLIDserver DDI menyederhanakan manajemen jaringan, meningkatkan efisiensi operasional, dan memperkuat postur keamanan siber perusahaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 219739);
