INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123095', 62123095, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Sewa Layanan Google Cloud Platform (Warning-INA-TEWS)', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 240000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 BLN', 'BMKG mempunyai tugas utama untuk memberikan informasi tentang kebencanaan. Informasi disampaikan melalui beberapa media, salah satunya menggunakan website dan aplikasi mobile. Dengan semakin banyaknya user yang mengakses informasi, maka diperlukan dukungan servis dari layanan informasi yang baik juga. Untuk mendukung penyampaian layanan informasi diperlukan layanan komputasi awan. Dibutuhkan setidaknya 4 komponen utama untuk membangun aplikasi website berbasis komputasi awan. Empat layanan tersebut adalah Platform-as-a-Service (PaaS), Object Storage, VPS, dan CDN. Dengan penjelasan: PaaS: Layanan pengembang software secara hosting yang mudah dan terukur. Pengembang dapat juga menggunakan software developer kit (SDK) untuk mengembangkan produk software yang terkait penyedia PaaS, Object Storage: Penyimpanan berbasis cloud untuk menyimpan berkas yang bersifat statis dan dinamis, seperti gambar, video, audio, XML, JSON, CSS, dan Javascript, VPS (Virtual Private Server): layanan server virtual yang memiliki sumber daya yang terdedikasi khusus untuk satu pengguna, berbeda dengan shared hosting dimana sumber daya komputasi yang sama digunakan oleh beberapa pengguna, CDN (Content Delivery Network): rangkaian server yang tersebar di berbagai lokasi geografis di seluruh dunia, yang berfungsi untuk mempercepat pengiriman konten website.', 'Perangkat yang digunakan untuk sewa komputasi awan adalah : Platform-as-a-Service (Instance class: F1, Instance hours : 1,825 hours, Environment: Standard environment, Runtime: PHP), Object Storage (Kapasitas: 500 GB, Class: Standard storage, Class A operations: 6 million, Class B operations: 1,000 million, Multi-region Egress - Asia: 100 GiB, Inter-region Egress - North America: 1,000 GiB), CDN: (Egress Asia/Pacific: 10 GiB, Egress China: 1 GiB, Egress Europe: 2 GiB, Egress Oceania: 1 GiB, Egress North America: 3 GiB, Egress South America: 1 GiB), VPS: (Instance: 3, vCPU: 2, RAM: 8GB, Boot Disk: 100GB, Static IP Public: 2) Terintegrasi dengan platform layanan website warning.bmkg.go.id dan inatews.bmkg.go.id dan platform komputasi awan untuk layanan Authoritative name lookups domain name system', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 219893);
